def is_balanced(root):
    def check_balance(node):
        if not node:
            return (True, 0)

        # Check the left subtree
        left_is_balanced, left_height = check_balance(node.left)
        if not left_is_balanced:
            return (False, 0)

        # Check the right subtree
        right_is_balanced, right_height = check_balance(node.right)
        if not right_is_balanced:
            return (False, 0)

        # Calculate height
        height_diff = abs(left_height - right_height)
        if height_diff > 1:
            return (False, 0)

        return (True, 1 + max(left_height, right_height))

    return check_balance(root)[0]
```

This approach ensures that the function provides immediate feedback about the balance condition, which is crucial for an accurate result.

